<?php
namespace App\Commands\AiOps;
use App\Commands\SafeBaseCommand; use App\Commands\Support\SubsCommandTrait;
class Audit extends SafeBaseCommand { use SubsCommandTrait; protected $group='AiOps'; protected $name='aiops:audit'; protected $description='Audit aiops runtime and entrypoints'; protected $options=['--json'=>'JSON']; public function run(array $params){$this->parseParams($params);$json=$this->optBool('json');$issues=[]; if(!is_file(ROOTPATH.'aiops/bridge-8500.js')){$issues[]='Missing bridge-8500.js';} if(!is_file(ROOTPATH.'aiops/bin/n8n-start-safe.sh')){$issues[]='Missing n8n start wrapper';} $status=$this->mgr()->status('aiops.n8n'); if($status['running'] && !$status['port_listening']){$issues[]='PID alive but n8n port not listening';} $report=['status'=>empty($issues)?'ok':'degraded','issues'=>$issues,'checked_at'=>date('c'),'n8n'=>$status]; $path=$this->writeDoc('audits','aiops-audit-'.date('Y-m-d').'.json',$report); $report['report']=$path; $this->emit($report,$json); return empty($issues)?EXIT_SUCCESS:EXIT_ERROR; }}
